package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class JsonWriter_value_TriageGen0Test {

    @Test
    public void testValueLong_Positive() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter writer = new JsonWriter(out);

        writer.beginObject();
        writer.name("testKey");
        JsonWriter result = writer.value(12345L);
        writer.endObject();

        Assert.assertEquals("{\"testKey\":12345}", out.toString());
        // Check fluid API (return type)
        Assert.assertEquals(writer, result);
    }

    @Test
    public void testValueLong_Negative() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter writer = new JsonWriter(out);

        writer.beginArray();
        writer.value(-98765L);
        writer.endArray();

        Assert.assertEquals("[-98765]", out.toString());
    }

    @Test
    public void testValueLong_Zero() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter writer = new JsonWriter(out);

        writer.beginObject();
        writer.name("zero");
        writer.value(0L);
        writer.endObject();

        Assert.assertEquals("{\"zero\":0}", out.toString());
    }

    @Test
    public void testValueLong_LongMaxValue() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter writer = new JsonWriter(out);
        long maxValue = Long.MAX_VALUE;

        writer.beginArray();
        writer.value(maxValue);
        writer.endArray();

        Assert.assertEquals("[" + maxValue + "]", out.toString());
    }

    @Test
    public void testValueLong_LongMinValue() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter writer = new JsonWriter(out);
        long minValue = Long.MIN_VALUE;

        writer.beginArray();
        writer.value(minValue);
        writer.endArray();

        Assert.assertEquals("[" + minValue + "]", out.toString());
    }

    @Test(expected = IOException.class)
    public void testValueLong_ThrowsIOException() throws IOException {
        // Create a writer that throws IOException on write
        Writer throwingWriter = new Writer() {
            @Override
            public void write(char[] cbuf, int off, int len) throws IOException {
                throw new IOException("Simulated IO error");
            }

            @Override
            public void flush() throws IOException {}

            @Override
            public void close() throws IOException {}
        };

        JsonWriter writer = new JsonWriter(throwingWriter);
        writer.beginArray();
        // This should trigger IOException inside Long.toString or out.write
        writer.value(10L);
    }
}
